def dedupe(seq):
    seen = set()
    out = []
    for x in seq:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out


def dedupe_fast(seq):
    return list(dict.fromkeys(seq))


data = [3, 1, 3, 2, 1]
print(f"dedupe(data) -> {dedupe(data)!r}")
print(f"dedupe_fast(data) -> {dedupe_fast(data)!r}")
print(f"sorted(set(data)) -> {sorted(set(data))!r}")
print(f"dedupe([1, True, 1.0]) -> {dedupe([1, True, 1.0])!r}")
